#!/usr/bin/env python
"""HCL-TR v0.4 — 数据管线 + tokenizer + chunkwise 冒烟（Kaggle T4x2，自包含）。"""
import subprocess, sys, os, time, base64, traceback, re, json, random
os.environ.setdefault("PYTORCH_CUDA_ALLOC_CONF", "expandable_segments:True")

RUN_LOG = "/kaggle/working/run.log"
def log(m):
    s = f"[{time.strftime('%H:%M:%S')}] {m}"
    print(s, flush=True)
    try:
        with open(RUN_LOG, "a") as f: f.write(s + "\n")
    except Exception: pass

import signal

class StageTimeout(Exception): pass

def _alarm(signum, frame): raise StageTimeout("stage 超时")

def stage(name, timeout=None):
    """带硬超时的阶段包装：超时即中断，绝不无限挂起。"""
    def deco(fn):
        def w(*a, **k):
            log(f"=== {name} START === (timeout={timeout}s)"); t=time.time()
            old = None
            if timeout:
                old = signal.signal(signal.SIGALRM, _alarm)
                signal.alarm(int(timeout))
            try:
                r=fn(*a,**k); log(f"=== {name} OK ({time.time()-t:.1f}s) ==="); return r
            except Exception as e:
                log(f"=== {name} FAIL: {type(e).__name__}: {e} ===")
                log(traceback.format_exc()[-1500:]); raise
            finally:
                if timeout:
                    signal.alarm(0); signal.signal(signal.SIGALRM, old)
        return w
    return deco

PAYLOAD = """

"""

ZH_REPO = "opencsg/chinese-fineweb-edu-v2"

def _fetch_zh(limit_docs=400000, max_files=6, cache="/kaggle/working/zh"):
    """从 HF 拉中文语料：直接下载 parquet 后本地读，**不用 datasets 流式**
    （流式迭代 parquet 曾卡死 4+ 小时）。"""
    import os
    try:
        from huggingface_hub import list_repo_files, hf_hub_download
        import pyarrow.parquet as pq
    except Exception as e:
        log(f"  zh deps 缺失: {e}"); return []
    os.makedirs(cache, exist_ok=True)
    files = [f for f in list_repo_files(ZH_REPO, repo_type="dataset") if f.endswith(".parquet")]
    files = sorted(files)[:max_files]
    log(f"  zh parquet files: {files}")
    docs = []
    for f in files:
        try:
            local = hf_hub_download(ZH_REPO, f, repo_type="dataset", cache_dir=cache)
            tbl = pq.read_table(local)
            cols = tbl.column_names
            col = "content" if "content" in cols else ("text" if "text" in cols else cols[0])
            for x in tbl.column(col).to_pylist():
                if x: docs.append(x)
                if len(docs) >= limit_docs: break
            log(f"  zh {f}: total {len(docs)} docs")
            if len(docs) >= limit_docs: break
        except Exception as e:
            log(f"  zh {f} 失败: {type(e).__name__}: {e}")
    return docs


def _iter_jsonl(path, field="text", limit=10**9):
    """有界读取 JSONL 前 limit 行，取指定字段。纯本地 IO，不走网络。"""
    import json as _json
    out = []
    with open(path, "r", encoding="utf-8", errors="ignore") as f:
        for line in f:
            if len(out) >= limit: break
            line = line.strip()
            if not line: continue
            try:
                r = _json.loads(line)
            except Exception:
                continue
            t = r.get(field) or r.get("content") or r.get("text") or ""
            if t: out.append(t)
    return out


def _find_inputs():
    """在 /kaggle/input 下找 C4 / FineWeb-Edu / Gutenberg 的 jsonl。"""
    import glob as _g
    files = _g.glob("/kaggle/input/**/*.jsonl", recursive=True)
    c4 = [f for f in files if "c4" in f.lower()]
    fw = [f for f in files if "fw" in f.lower() or "fineweb" in f.lower()]
    gb = [f for f in files if "gutenberg" in f.lower()]
    log(f"input jsonl: c4={c4[:1]} fw={fw[:1]} gb={gb[:1]} total={len(files)}")
    return (c4[0] if c4 else None), (fw[0] if fw else None), (gb[0] if gb else None)


def _doc_len_stats(docs, tok=None, name=""):
    if not docs: return
    chars = [len(d) for d in docs]
    chars.sort()
    med = chars[len(chars)//2]
    p90 = chars[int(len(chars)*0.9)]
    if tok is not None:
        toks = [len(tok.encode(d).ids) for d in docs[:2000]]
        toks.sort(); med_t = toks[len(toks)//2]; p90_t = toks[int(len(toks)*0.9)]
        log(f"  {name}: n={len(docs)} chars(med={med},p90={p90}) "
            f"tokens(med={med_t},p90={p90_t})")
    else:
        log(f"  {name}: n={len(docs)} chars(med={med},p90={p90})")


SMOKE_TOKENS = 5_000_000       # A/B 探针预算
N_SHARDS = 0                   # 分片总数，构包阶段写入
TOK_SAMPLE_DOCS = 20000        # 训 tokenizer 的样本量（10M 正式跑）

