@stage("sample_and_tokenizer", timeout=1800)
def do_tok():
    """取 en/zh 样本 → 训 64k BPE → 记录 hash。"""
    from hcl_tr.data.tokenizer import train_bpe, tokenizer_hash
    c4f, fwf, gbf = _find_inputs()
    if not c4f:
        raise RuntimeError("找不到挂载的 C4 jsonl（检查 dataset_sources）")
    en = _iter_jsonl(c4f, limit=TOK_SAMPLE_DOCS)
    if fwf:
        en += _iter_jsonl(fwf, limit=TOK_SAMPLE_DOCS // 2)
    if gbf:
        gb = _iter_jsonl(gbf, limit=max(200, TOK_SAMPLE_DOCS // 20))   # 书很长，少取即可
        en += gb
    zh_sample = _fetch_zh(limit_docs=max(500, TOK_SAMPLE_DOCS // 10), max_files=1)
    zh = zh_sample
    zh = []   # 探针先只做英文；中文源后续接
    log(f"en sample docs={len(en)} zh={len(zh)}")
    # 混合喂给 trainer：85/15
    corpus=[]
    for i in range(max(len(en),len(zh))):
        if i < len(en): corpus.append(en[i])
        if i*0.15/0.85 < len(zh) and i % 6 == 0 and int(i*0.15/0.85) < len(zh):
            corpus.append(zh[int(i*0.15/0.85)])
    p=train_bpe(corpus, "/kaggle/working/tokenizer", vocab_size=64000)
    h=tokenizer_hash(p)
    log(f"tokenizer trained vocab=64000 hash={h[:16]}")
    open("/kaggle/working/tokenizer_hash.txt","w").write(h)
    return p

@stage("build_shards", timeout=2400)
def do_shards():
    """MinHash 去重 + 教育分 + 去污染 → 写出 SMOKE_TOKENS 的分片，产出 manifest。"""
    import numpy as np
    from datasets import load_dataset
    from tokenizers import Tokenizer
    from hcl_tr.data.pipeline import (MinHashConfig, minhash_dedup_fast as minhash_dedup, edu_filter,
                                      decontaminate, build_frozen_manifest, MixSource)
    from hcl_tr.data.prefetch import write_shard

    tok = Tokenizer.from_file("/kaggle/working/tokenizer/tokenizer.json")
    th = open("/kaggle/working/tokenizer_hash.txt").read().strip()

    c4f, fwf, gbf = _find_inputs()
    if not c4f:
        raise RuntimeError("找不到挂载的 C4 jsonl")
    # 按「配额 / 每篇预估 token」估算文档数，只读够用的量（全量去重曾超时 40min）
    est = {"en_c4": (1347, 4.0), "en_fineweb_edu": (2760, 4.0),
           "en_gutenberg": (11808, 4.0), "zh_fineweb_edu": (1372, 1.5)}
    W = {"en_c4":0.34,"en_fineweb_edu":0.30,"en_gutenberg":0.21,"zh_fineweb_edu":0.15}
    def budget(name):
        chars_per_doc, cpt = est[name]
        toks_per_doc = max(50, chars_per_doc / cpt)
        return int(SMOKE_TOKENS * W[name] / toks_per_doc * 1.6) + 100
    en_c4 = _iter_jsonl(c4f, limit=budget("en_c4"))
    en_fw = _iter_jsonl(fwf, limit=budget("en_fineweb_edu")) if fwf else []
    en_gb = _iter_jsonl(gbf, limit=budget("en_gutenberg")) if gbf else []
    zh = _fetch_zh(limit_docs=budget("zh_fineweb_edu"), max_files=3)
    log(f"doc budget: c4={budget('en_c4')} fw={budget('en_fineweb_edu')} "
        f"gb={budget('en_gutenberg')} zh={budget('zh_fineweb_edu')}")
    log(f"docs: c4={len(en_c4)} fw={len(en_fw)} gb={len(en_gb)} zh={len(zh)}")
    for _n,_d in [("c4",en_c4),("fw",en_fw),("gb",en_gb),("zh",zh)]:
        _doc_len_stats(_d, name=_n)

    # 质量过滤 + 去重（逐路做，避免跨语言误判重复）
    kept = {}
    for name, docs in [("en_c4",en_c4),("en_fineweb_edu",en_fw),
                       ("en_gutenberg",en_gb),("zh_fineweb_edu",zh)]:
        ki = edu_filter(docs, min_score=0.35)          # 冒烟放宽，正式用 0.5
        sub = [docs[i] for i in ki]
        dk = minhash_dedup(sub, MinHashConfig(num_perm=64,bands=16,threshold=0.8))
        kept[name]=[sub[i] for i in dk]
        log(f"  {name}: {len(docs)} -> edu {len(sub)} -> dedup {len(kept[name])}")

    # 去污染（对 S-NIAH 风格样本）：冒烟用极小 eval 集占位
    eval_texts = ["What is the magic number? The secret code is magic-123456."]
    for name in kept:
        try:
            idx = decontaminate(kept[name], eval_texts, n=13, max_drop_ratio=0.05)
            kept[name]=[kept[name][i] for i in idx]
        except Exception as e:
            log(f"  decontam {name}: {e}")

    weights={"en_c4":0.34,"en_fineweb_edu":0.30,"en_gutenberg":0.21,"zh_fineweb_edu":0.15}
    live={k:v for k,v in kept.items() if v}
    tot=sum(weights[k] for k in live)
    srcs=[MixSource(k, v, weights[k]/tot) for k,v in live.items()]
    man = build_frozen_manifest(srcs, 64000, th, 0, 0.35, 0.8,
                                extra={"note":"smoke pack; 正式包用 edu>=0.5 与全量去污染"})
    log(f"data_mix_hash={man['data_mix_hash'][:16]}")

    # 编码并写分片
    buf=[]; idx=0; written=0
    target=SMOKE_TOKENS
    order=[]
    # 先按配额把各源各自编码成数组
    from hcl_tr.data.pipeline import interleave_token_streams
    streams = {}
    for s in srcs:
        quota=int(target*s.weight); got=0; parts=[]
        for d in s.docs:
            ids=tok.encode(d).ids
            parts.extend(ids); got+=len(ids)
            if got>=quota: break
        streams[s.name]=np.asarray(parts[:quota],dtype=np.int64)
        log(f"  {s.name}: {len(streams[s.name])} tokens")
    # 按权重交错成一条流（否则末段会集中同一领域，loss 会崩）
    wmap={s.name: s.weight for s in srcs}
    # 实际产出与目标配额的对比：数据不足时 mix 会静默漂移，必须显式告警
    for n in streams:
        want_n = int(target * wmap.get(n, 0))
        got_n = len(streams[n])
        if want_n and got_n < want_n * 0.9:
            log(f"  [WARN] {n} 数据不足: 实得 {got_n} / 目标 {want_n}")
    mixed=interleave_token_streams(streams, wmap, total=target, chunk=8192)
    # 实际 token 占比（用于记录真实 mix，而非名义权重）
    realized = {n: round(float((mixed == streams[n][0]).mean()), 4) for n in streams if len(streams[n])}
    log(f"  realized mix (近似): {realized}")
    log(f"  interleaved: {mixed.size} tokens; head ratio="
        f"{[(float((mixed[:8000]==streams[n][0]).mean()), n) for n in streams]}")
    buf=mixed.tolist()
    while buf:
        arr=np.asarray(buf[:2_000_000],dtype=np.uint16)
        write_shard("/kaggle/working/tokens", idx, arr); idx+=1; written+=arr.size
        buf=buf[len(arr):]
    log(f"shards written: {written} tokens in {idx} shards")
    global N_SHARDS
    N_SHARDS = idx
    import json
    open("/kaggle/working/manifest.json","w").write(json.dumps(man,indent=2,ensure_ascii=False))

@stage("train_10m", timeout=9000)
def do_train():
    import torch, json
    from pathlib import Path
    from hcl_tr.data.prefetch import ShardStream
    from hcl_tr.models.backbone import HybridBackbone
    from hcl_tr.train.loop import TrainConfig, train_ddp, grad_accum_for_global_batch
    n=torch.cuda.device_count()
    mb=1; seq=8192; accum=16                             # 计划书口径：global=1*16*8192*2=262144
    log(f"train_10m: n_gpu={n} mb={mb} accum={accum} seq={seq} (chunkwise) shards={N_SHARDS}")
    cfg=TrainConfig(seq_len=seq, micro_batch_per_gpu=mb, grad_accum=accum,
                    lr=2e-4, warmup_tokens=1_000_000, total_tokens=SMOKE_TOKENS,
                    use_fp16=True, log_every=1, ckpt_every_tokens=5_000_000,
                    out_dir="/kaggle/working/out")
    m=HybridBackbone(vocab_size=64000,d_model=640,n_layer=12,n_head=10,
                     grad_checkpointing=True, gdn2_chunk=512)
    log(f"params={sum(p.numel() for p in m.parameters())/1e6:.2f}M chunkwise={m.use_chunkwise}")
    train_ddp({"vocab_size":64000,"d_model":640,"n_layer":12,"n_head":10,
               "grad_checkpointing":True, "gdn2_chunk":512},
              "/kaggle/working/tokens", cfg, world_size=n,
              ddp_kwargs={"max_cache_bytes": int(6e9), "planned_shards": N_SHARDS})
    Path("/kaggle/working/out").mkdir(exist_ok=True)
    Path("/kaggle/working/out/smoke_done.json").write_text(json.dumps({"ok":True}))


@stage("profile_throughput", timeout=1800)
def do_profile():
    """剖析吞吐瓶颈：序列长度 / 梯度检查点 / chunk 大小 / 层类型占比。"""
    import torch, json, time
    from hcl_tr.models.backbone import HybridBackbone
    from hcl_tr.train.loop import chunked_cross_entropy

    def bench(model, seq, iters=3, warmup=1):
        mdl = model.cuda()
        opt = torch.optim.AdamW(mdl.parameters(), lr=1e-4)
        ids = torch.randint(0, 64000, (1, seq), device="cuda")
        def step():
            logits = mdl(ids[:, :-1])
            loss = chunked_cross_entropy(logits, ids[:, 1:], chunk_tokens=2048)
            loss.backward(); opt.step(); opt.zero_grad(set_to_none=True)
        for _ in range(warmup):
            try: step()
            except RuntimeError as e:
                return f"OOM:{str(e)[:60]}"
        torch.cuda.synchronize(); t = time.time()
        for _ in range(iters): step()
        torch.cuda.synchronize(); dt = (time.time() - t) / iters
        return round(seq * iters / dt, 1)

    res = {}
    log(f"GPU: {torch.cuda.get_device_properties(0).name}")
    for seq in [2048, 4096, 8192]:
        for ckpt in [False, True]:
            torch.cuda.empty_cache()
            try:
                m = HybridBackbone(vocab_size=64000, d_model=640, n_layer=12, n_head=10,
                                   grad_checkpointing=ckpt)
                tps = bench(m, seq)
                res[f"seq{seq}_ckpt{int(ckpt)}"] = tps
                log(f"  seq={seq} ckpt={ckpt}: {tps} tok/s")
                del m
            except Exception as e:
                res[f"seq{seq}_ckpt{int(ckpt)}"] = f"ERR:{type(e).__name__}"
                log(f"  seq={seq} ckpt={ckpt}: ERR {e}")
            torch.cuda.empty_cache()
    for c in [16, 32, 64, 128]:
        torch.cuda.empty_cache()
        try:
            m = HybridBackbone(vocab_size=64000, d_model=640, n_layer=12, n_head=10,
                               grad_checkpointing=True, gdn2_chunk=c)
            tps = bench(m, 4096)
            res[f"chunk{c}_seq4096"] = tps
            log(f"  chunk={c}: {tps} tok/s")
            del m
        except Exception as e:
            res[f"chunk{c}_seq4096"] = f"ERR:{type(e).__name__}"
        torch.cuda.empty_cache()
    # 层类型占比：全注意力 vs 全 GDN-2
    for ratio, name in [(1, "all_attn"), (10**9, "all_gdn2")]:
        torch.cuda.empty_cache()
        try:
            m = HybridBackbone(vocab_size=64000, d_model=640, n_layer=12, n_head=10,
                               grad_checkpointing=True, attn_ratio=ratio)
            tps = bench(m, 4096)
            res[name] = tps
            log(f"  {name}: {tps} tok/s")
            del m
        except Exception as e:
            res[name] = f"ERR:{type(e).__name__}"
        torch.cuda.empty_cache()
    open("/kaggle/working/profile.json","w").write(json.dumps(res, indent=2))
    log(f"profile: {json.dumps(res)}")



@stage("graph_bench", timeout=3600)
def do_graph_bench():
    import torch, json, time
    from hcl_tr.models.backbone import HybridBackbone
    from hcl_tr.train.loop import chunked_cross_entropy

    SEQ, CH = 2048, 18
    def build(mode):
        m = HybridBackbone(vocab_size=64000, d_model=640, n_layer=12, n_head=10,
                           grad_checkpointing=True, gdn2_chunk_override=CH,
                           gdn2_solve_mode=mode).cuda()
        for blk in m.blocks:
            mx = getattr(blk, "mixer", None)
            if mx is not None and hasattr(mx, "_chunk_eff"): mx._chunk_eff = CH
        return m

    def eager(mode):
        torch.cuda.empty_cache()
        m = build(mode); opt = torch.optim.AdamW(m.parameters(), lr=1e-4, fused=True)
        ids = torch.randint(0, 64000, (1, SEQ), device="cuda")
        def stp():
            lg = m(ids[:, :-1]); l = chunked_cross_entropy(lg, ids[:, 1:], chunk_tokens=512)
            l.backward(); opt.step(); opt.zero_grad(set_to_none=True)
        for _ in range(2): stp()
        torch.cuda.synchronize(); t=time.time()
        for _ in range(3): stp()
        torch.cuda.synchronize(); return round(SEQ*3/(time.time()-t),1)

    def captured(mode):
        torch.cuda.empty_cache()
        m = build(mode); opt = torch.optim.AdamW(m.parameters(), lr=1e-4, fused=True)
        ids = torch.randint(0, 64000, (1, SEQ), device="cuda")
        def stp():
            lg = m(ids[:, :-1]); l = chunked_cross_entropy(lg, ids[:, 1:], chunk_tokens=512)
            l.backward(); opt.step(); opt.zero_grad(set_to_none=False)
        s_ = torch.cuda.Stream(); s_.wait_stream(torch.cuda.current_stream())
        with torch.cuda.stream(s_):
            for _ in range(3): stp()
        torch.cuda.current_stream().wait_stream(s_); torch.cuda.synchronize()
        torch.cuda.empty_cache()
        g = torch.cuda.CUDAGraph()
        with torch.cuda.graph(g):
            stp()
        torch.cuda.synchronize()
        t=time.time()
        for _ in range(3): g.replay()
        torch.cuda.synchronize(); return round(SEQ*3/(time.time()-t),1)

    res = {}
    for name, fn, mode in [("eager_solver", eager, "solver"),
                           ("eager_neumann", eager, "neumann"),
                           ("graph_solver", captured, "solver"),
                           ("graph_neumann", captured, "neumann")]:
        try: v = fn(mode)
        except Exception as e: v = f"ERR:{type(e).__name__}:{str(e)[:120]}"
        res[name] = v; log(f"  {name}: {v}")
        torch.cuda.empty_cache()
    open("/kaggle/working/graph.json","w").write(json.dumps(res, indent=2))
    log(f"graph bench: {json.dumps(res)}")


@stage("ab_probe", timeout=14000)
def do_ab_probe():
    """A_log 上界 A/B 探针：16（计划书）vs 2.4（提速候选）。
    同数据、同超参，仅 A_log 不同；记录 loss 曲线与 2K/4K needle 测试。
    """
    import torch, json, time, random, os
    from pathlib import Path
    from hcl_tr.train.loop import TrainConfig, train_ddp
    from hcl_tr.models.backbone import HybridBackbone
    from tokenizers import Tokenizer

    TOK = "/kaggle/working/tokenizer/tokenizer.json"
    if not os.path.exists(TOK):
        cands = list(Path("/kaggle/working/tokenizer").rglob("*.json"))
        TOK = str(cands[0]) if cands else TOK
    tok = Tokenizer.from_file(TOK)
    n = torch.cuda.device_count()
    SEQ = 8192

    FILLER = ("The grass is green. The sky is blue. The sun rises in the east. "
              "Water flows downhill. Birds fly in the sky. Trees grow tall.")

    def needle_prompt(L_words, needle):
        filler = (FILLER + " ") * (L_words // 12 + 2)
        words = filler.split()[:L_words]
        pos = len(words) // 2
        words = words[:pos] + [f"The secret code is {needle}."] + words[pos:]
        return " ".join(words) + "\n\nWhat is the magic number? Answer:"

    def greedy(model, prompt, max_new=8):
        ids = tok.encode(prompt).ids[-SEQ + max_new:]
        x = torch.tensor([ids], device="cuda")
        for _ in range(max_new):
            with torch.no_grad():
                lg = model(x[:, -SEQ:])
            nxt = int(lg[0, -1].argmax())
            x = torch.cat([x, torch.tensor([[nxt]], device="cuda")], dim=1)
        return tok.decode(x[0, len(ids):].tolist())

    def read_new_log(offset):
        p = "/kaggle/working/run.log"
        if not os.path.exists(p): return offset, []
        with open(p, encoding="utf-8", errors="ignore") as f:
            f.seek(offset); return f.tell(), f.read().splitlines()

    res = {}
    for a_max in [16.0, 2.4]:
        name = f"alog{a_max}"
        out = f"/kaggle/working/out_{name}"
        cfg = TrainConfig(seq_len=SEQ, micro_batch_per_gpu=1, grad_accum=16,
                          lr=2e-4, warmup_tokens=1_000_000, total_tokens=5_000_000,
                          use_fp16=True, log_every=1, ckpt_every_tokens=5_000_000,
                          out_dir=out)
        log(f"=== A/B {name} START ===")
        off = os.path.getsize("/kaggle/working/run.log") if os.path.exists("/kaggle/working/run.log") else 0
        train_ddp({"vocab_size":64000,"d_model":640,"n_layer":12,"n_head":10,
                   "grad_checkpointing":True, "gdn2_chunk":512,
                   "gdn2_a_log_max": a_max},
                  "/kaggle/working/tokens", cfg, world_size=n,
                  ddp_kwargs={"max_cache_bytes": int(6e9), "planned_shards": N_SHARDS})
        _, lines = read_new_log(off)
        curve = []
        for ln in lines:
            m_ = re.search(r"step (\d+) loss ([0-9.]+)", ln)
            if m_: curve.append((int(m_.group(1)), float(m_.group(2))))
        # needle 测试
        torch.cuda.empty_cache()
        mdl = HybridBackbone(vocab_size=64000, d_model=640, n_layer=12, n_head=10,
                             grad_checkpointing=False, gdn2_chunk=512,
                             gdn2_a_log_max=a_max).cuda()
        from hcl_tr.checkpoint import safe_torch_load, sha256_file
        ck = safe_torch_load(f"{out}/final.pt", sha256=sha256_file(f"{out}/final.pt"),
                             map_location="cuda")
        mdl.load_state_dict(ck["model"]); mdl.eval()
        hits = {}
        for L in [2048, 4096]:
            ok = 0
            for k in range(4):
                nd = f"magic-{random.randrange(10**6):06d}"
                pred = greedy(mdl, needle_prompt(L, nd))
                ok += int(nd.lower() in pred.lower())
            hits[L] = f"{ok}/4"
        del mdl; torch.cuda.empty_cache()
        res[name] = {"curve": curve[-8:], "final_loss": curve[-1][1] if curve else None,
                     "needle": hits}
        log(f"=== A/B {name} DONE: {json.dumps(res[name])} ===")
    open("/kaggle/working/ab_probe.json", "w").write(json.dumps(res, indent=2, ensure_ascii=False))


